import{_ as p,a0 as o,w as d,s as u,I as i,x as a,a1 as t,A as e,ao as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const D=JSON.parse('{"title":"在 Linux Mint 中安裝 KDE Plasma 桌面環境 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux Mint 中安裝 KDE Plasma 桌面環境 | LCTT (202308) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux Mint 中安裝 KDE Plasma 桌面環境 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux Mint 中安裝 KDE Plasma 桌面環境 | LCTT (202308) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202308/20230721.4 ⭐️ Install KDE Plasma Desktop in Linux Mint An Experiment","title":"在 Linux Mint 中安裝 KDE Plasma 桌面環境","tag":"202308","desc":""},"relativePath":"202308/20230721.4 ⭐️ Install KDE Plasma Desktop in Linux Mint An Experiment.md","filePath":"[post].md"}'),r={name:"202308/20230721.4 ⭐️ Install KDE Plasma Desktop in Linux Mint An Experiment.md"};function g(h,s,m,k,b,x){const n=o("Link");return d(),u("div",null,[s[19]||(s[19]=i("h1",{id:"在-linux-mint-中安裝-kde-plasma-桌面環境",tabindex:"-1"},[a("在 Linux Mint 中安裝 KDE Plasma 桌面環境 "),i("a",{class:"header-anchor",href:"#在-linux-mint-中安裝-kde-plasma-桌面環境","aria-label":"Permalink to “在 Linux Mint 中安裝 KDE Plasma 桌面環境”"},"​")],-1)),s[20]||(s[20]=i("p",null,[i("img",{src:"https://img.linux.net.cn/data/attachment/album/202308/10/153023isl2b4y771f34h79.jpg",alt:""})],-1)),s[21]||(s[21]=i("blockquote",null,[i("p",null,"下面介紹如何在 Linux Mint 中安裝 KDE Plasma 桌面環境，並進行了一些微調。")],-1)),i("p",null,[t(n,{href:"https://www.debugpoint.com/linux-mint"},{default:e(()=>[...s[0]||(s[0]=[a("Linux Mint",-1)])]),_:1}),s[1]||(s[1]=a(" 是最流行的和用户友好的 Linux 發行版，以其易用性和穩定性而聞名。雖然 Linux Mint 中默認的 Cinnamon 桌面環境提供了友好愉快的體驗，但也有一些用户可能想要探索其它的桌面環境，以進一步定製自己的 Linux 體驗。KDE Plasma 是另一個著名的桌面環境，提供了一種現代化的特色功能豐富的界面。",-1))]),s[22]||(s[22]=l('<p>然而，Linux Mint 從未正式提供過 KDE Plasma 。但是這裏有一種在 Linux Mint 基礎之上安裝 KDE Plasma 桌面環境的方法。讓我們一起嘗試一下。</p><blockquote><p><strong>注意</strong>: 不要在你的有重要數據的穩定系統中嘗試這些步驟。有風險。</p></blockquote><p><img src="https://www.debugpoint.com/wp-content/uploads/2023/07/Linux-Mint-with-KDE-Plasma.jpg" alt="Linux Mint with KDE Plasma"></p><h3 id="在-linux-mint-中安裝-kde-plasma-桌面環境-1" tabindex="-1">在 Linux Mint 中安裝 KDE Plasma 桌面環境 <a class="header-anchor" href="#在-linux-mint-中安裝-kde-plasma-桌面環境-1" aria-label="Permalink to “在 Linux Mint 中安裝 KDE Plasma 桌面環境”">​</a></h3><p>在 Linux Mint 發行版中，有三種主要組件來安裝 KDE Plasma 桌面環境。它們是 <code>kde-full</code>、<code>kde-standard</code> 和 <code>kde-plasma-desktop</code> 。</p>',5)),i("p",null,[t(n,{href:"https://packages.ubuntu.com/kinetic/kde-full"},{default:e(()=>[...s[2]||(s[2]=[a("kde-full",-1)])]),_:1}),s[3]||(s[3]=a(" 軟件包集包含完整的 KDE Plasma 桌面環境。kde-standard 是最小的版本，kde-plasma-desktop 僅是桌面環境。",-1))]),s[23]||(s[23]=l(`<p>如果你將要嘗試安裝 KDE Plasma 桌面環境，我將建議安裝 kde-full 軟件包。</p><p>首先，打開一個終端，確保你的 Linux Mint 版本是已更新的。確保你執行了一次重新啓動。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt update &amp;&amp; sudo apt upgrade -y</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>reboot</span></span></code></pre></div><p>其次，在終端中，運行下面的命令來安裝完整的 KDE 軟件包。由於 Linux Mint 是基於 Ubuntu LTS 版本的，所以，你應該會獲取基於當前正在持續更新的 Kubuntu LTS Plasma 版本的 KDE Plasma 版本。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install kde-full</span></span></code></pre></div><p>完整的下載體積有點大。針對當前的 Linux Mint 版本，它大約是 1.5 GB ，整個安裝過程可能需要 20 分鐘。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2023/07/Installing-KDE-Plasma-in-Linux-Mint.jpg" alt="Installing KDE Plasma in Linux Mint"></p><p>在安裝過程中，你需要選擇顯示管理器，因為 KDE Plasma 使用 SDDM 。出現提示時，在下面的屏幕中選擇 SDDM 。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2023/07/Selecting-SDDM-as-display-manager.jpg" alt="Selecting SDDM as display manager"></p><p>在安裝完成後，你需要在 SDDM 配置文件中修改其中一個備選項以阻止在登錄過程中彈出一個空的聯機鍵盤。為此，使用 nano 或任意一個編輯器來打開下面的文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo nano /etc/sddm.conf</span></span></code></pre></div><p>接下來，添加下面的行。保存並退出。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[General]InputMethod=</span></span></code></pre></div><p>最後，重新啓動系統。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>reboot</span></span></code></pre></div><p>在登錄期間，你應該會看到 SDDM 登錄窗口，而不是 Linux Mint 的原來的登錄提示窗口。在窗口頂部，選擇 “Plasma” 會話並登錄。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2023/07/Choose-Plasma-as-Session.jpg" alt="Choose Plasma as Session"></p><h3 id="移除-cinnamon-、xfce-或-mate" tabindex="-1">移除 Cinnamon 、Xfce 或 MATE <a class="header-anchor" href="#移除-cinnamon-、xfce-或-mate" aria-label="Permalink to “移除 Cinnamon 、Xfce 或 MATE”">​</a></h3><p>在 KDE Plasma 安裝後，你可以移除 Cinnamon 、Xfce 或 MATE 桌面環境組件。如果你看到你的 KDE Plasma 工作的很好，那麼移除是安全的。使用下面的命令來移除它們，最後使用命令 <code>reboot</code> 來重新啓動。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt purge cinnamon</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt purge mate-desktop</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt purge</span></span>
<span class="line"><span>    xfce4-session</span></span>
<span class="line"><span>    xfwm4</span></span>
<span class="line"><span>    xfdesktop4</span></span>
<span class="line"><span>    xfconf</span></span>
<span class="line"><span>    xfce4-utils</span></span>
<span class="line"><span>    exo-utils</span></span>
<span class="line"><span>    xfce4-panel</span></span>
<span class="line"><span>    xfce4-terminal</span></span>
<span class="line"><span>    thunar</span></span></code></pre></div><h3 id="幾點注意事項" tabindex="-1">幾點注意事項 <a class="header-anchor" href="#幾點注意事項" aria-label="Permalink to “幾點注意事項”">​</a></h3><ul><li>你可能會發現：相比於 Cinnamon 桌面環境，KDE Plasma 的運行性能有一點慢，這是很明顯的。</li><li>Linux Mint 的壁紙、主題、圖標和光標文件可能會保留在系統中。如果你想的話，你可以移除它們。</li><li>Mint Plymouth 動畫應該也會保留，你可以手動移除它。</li><li>如果你在一個虛擬機中的系統中使用上述步驟，在從待機狀態喚醒時，SDDM 可能會崩潰。</li></ul><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>熱烈慶賀！你已經在你的 Linux Mint 系統上成功的安裝 Plasma 桌面環境。通過執行這些步驟，你現在可以訪問一個功能豐富的、視覺震撼的、可高度自定義的桌面環境。請謹慎使用！</p><p><em>（題圖：MJ/8944ad54-b64c-4761-b848-801215c63b56）</em></p><hr>`,29)),i("p",null,[s[5]||(s[5]=a("via: ",-1)),t(n,{href:"https://www.debugpoint.com/kde-plasma-linux-mint/"},{default:e(()=>[...s[4]||(s[4]=[a("https://www.debugpoint.com/kde-plasma-linux-mint/",-1)])]),_:1})]),i("p",null,[s[10]||(s[10]=a("作者：",-1)),t(n,{href:"https://www.debugpoint.com/author/admin1/"},{default:e(()=>[...s[6]||(s[6]=[a("Arindam",-1)])]),_:1}),s[11]||(s[11]=a(" 選題：",-1)),t(n,{href:"https://github.com/lkxed/"},{default:e(()=>[...s[7]||(s[7]=[a("lkxed",-1)])]),_:1}),s[12]||(s[12]=a(" 譯者：",-1)),t(n,{href:"https://github.com/robsean"},{default:e(()=>[...s[8]||(s[8]=[a("robsean",-1)])]),_:1}),s[13]||(s[13]=a(" 校對：",-1)),t(n,{href:"https://github.com/wxy"},{default:e(()=>[...s[9]||(s[9]=[a("wxy",-1)])]),_:1})]),i("p",null,[s[16]||(s[16]=a("本文由 ",-1)),t(n,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...s[14]||(s[14]=[a("LCTT",-1)])]),_:1}),s[17]||(s[17]=a(" 原創編譯，",-1)),t(n,{href:"https://linux.cn/"},{default:e(()=>[...s[15]||(s[15]=[a("Linux中國",-1)])]),_:1}),s[18]||(s[18]=a(" 榮譽推出",-1))])])}const P=p(r,[["render",g]]);export{D as __pageData,P as default};
